@page "/board"
@rendermode InteractiveServer
@using sv_e0182dc37d124eeabc110c7fa891bcb1
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="stats-card bg-primary bg-opacity-10 border-primary">
                <div class="stats-value">@allTasks.Count</div>
                <div class="stats-label">Total</div>
            </div>
        </div>
        @foreach (var col in columns)
        {
            <div class="col">
                <div class="stats-card bg-secondary bg-opacity-10">
                    <div class="stats-value">@GetTasksForColumn(col).Count</div>
                    <div class="stats-label">@col</div>
                </div>
            </div>
        }
        <div class="col">
            <div class="stats-card bg-danger bg-opacity-10 border-danger">
                <div class="stats-value">@allTasks.Count(t => t.DueDate < DateTime.Today)</div>
                <div class="stats-label">Overdue</div>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text"
               class="form-control"
               placeholder="Search tasks by title..."
               @bind="searchQuery"
               @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3 kanban-row">
        @foreach (var column in columns)
        {
            var colTasks = GetFilteredTasksForColumn(column);
            var colIndex = Array.IndexOf(columns, column);

            <div class="col-md-4">
                <div class="kanban-column">
                    <div class="kanban-header">
                        <span>@column</span>
                        <span class="badge bg-secondary rounded-pill">@colTasks.Count</span>
                    </div>

                    <div class="kanban-body">
                        @foreach (var task in colTasks)
                        {
                            var taskId = task.Id;
                            <div class="task-card">
                                <div class="task-title">@task.Title</div>
                                <div class="task-meta">
                                    <span class="text-muted">@task.Assignee</span>
                                    <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                                </div>
                                <div class="d-flex justify-content-between align-items-center mt-2">
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    <div class="btn-group btn-group-sm">
                                        @if (colIndex > 0)
                                        {
                                            var leftStatus = columns[colIndex - 1];
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@movingTaskIds.Contains(taskId)"
                                                    @onclick="() => MoveTaskAsync(taskId, leftStatus)"
                                                    title="Move to @leftStatus">
                                                &larr;
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            var rightStatus = columns[colIndex + 1];
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@movingTaskIds.Contains(taskId)"
                                                    @onclick="() => MoveTaskAsync(taskId, rightStatus)"
                                                    title="Move to @rightStatus">
                                                &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == column)
                        {
                            <div class="task-card add-form">
                                <div class="mb-2">
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Title" @bind="newTitle" />
                                </div>
                                <div class="mb-2">
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Assignee" @bind="newAssignee" />
                                </div>
                                <div class="mb-2">
                                    <select class="form-select form-select-sm" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                </div>
                                <div class="mb-2">
                                    <input type="date" class="form-control form-control-sm" @bind="newDueDate" />
                                </div>
                                <div class="d-flex gap-2">
                                    <button class="btn btn-primary btn-sm flex-fill"
                                            disabled="@isSaving"
                                            @onclick="SaveNewTaskAsync">
                                        @(isSaving ? "Saving..." : "Save")
                                    </button>
                                    <button class="btn btn-outline-secondary btn-sm flex-fill"
                                            disabled="@isSaving"
                                            @onclick="CancelAdd">
                                        Cancel
                                    </button>
                                </div>
                            </div>
                        }
                    </div>

                    @if (addingToColumn != column)
                    {
                        <div class="kanban-footer">
                            <button class="btn btn-outline-primary btn-sm w-100"
                                    @onclick="() => StartAdd(column)">
                                + Add Task
                            </button>
                        </div>
                    }
                </div>
            </div>
        }
    </div>
}

@code {
    private static readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchQuery = string.Empty;

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    private HashSet<int> movingTaskIds = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetTasksForColumn(string status)
        => allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredTasksForColumn(string status)
        => allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(searchQuery) ||
                         t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        movingTaskIds.Add(taskId);
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            movingTaskIds.Remove(taskId);
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        addingToColumn = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(newTitle) || addingToColumn is null)
            return;

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle.Trim(), newAssignee.Trim(), newPriority, newDueDate);
            allTasks.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isSaving = false;
        }
    }
}

.stats-card {
    border: 1px solid transparent;
    border-radius: 0.5rem;
    padding: 0.75rem;
