toolArgs.file_text:
.stats-card {
    border: 1px solid transparent;
    border-radius: 0.5rem;
    padding: 0.75rem;
    text-align: center;
}

.stats-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stats-label {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #6c757d;
}

.kanban-row {
    min-height: 400px;
}

.kanban-column {
    background: #f8f9fa;
    border-radius: 0.5rem;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.kanban-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 2px solid #dee2e6;
}

.kanban-body {
    flex: 1;
    padding: 0.75rem;
    overflow-y: auto;
}

.kanban-footer {
    padding: 0.75rem;
    border-top: 1px solid #dee2e6;
}

.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

.task-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.task-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.85rem;
}

.add-form {
    border: 2px dashed #0d6efd;
    background: #f0f4ff;
}

::deep .priority-high {
    background-color: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background-color: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background-color: #198754;
    color: #fff;
}

